import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './AppContent.module.css'

export interface AppContentProps extends ComponentProps<'main'> {
  /**
   * A column beside the page for a summary, a status or activity, in an
   * `aside` landmark. From 80rem of shell width it sits to the right and
   * scrolls on its own; below that it follows the page.
   */
  aside?: ReactNode
  /** The aside's accessible name. Give one when the page has more than one `aside`. */
  asideLabel?: string
}

/**
 * The page region of an App Shell: the `main` landmark, as one flat card
 * surface or as blocks on the canvas, whichever the Theme's `contentStyle`
 * picks, with an optional aside column. The shell renders it around its
 * children; it reads the shell's grid and canvas values, so it is not used
 * on its own.
 */
export function AppContent({ aside, asideLabel, className, children, ...props }: AppContentProps) {
  // `null`, `false` and `undefined` render nothing, so they are no aside either.
  const hasAside = aside != null && aside !== false
  return (
    <div className={cn(styles.content, hasAside && styles.withAside)}>
      <main tabIndex={-1} className={cn(styles.main, className)} {...props}>
        {children}
      </main>
      {hasAside && (
        // Focusable: side by side it scrolls on its own, and an aside of
        // plain text has nothing else a keyboard could scroll it with.
        <aside tabIndex={0} aria-label={asideLabel} className={styles.aside}>
          {aside}
        </aside>
      )}
    </div>
  )
}

/* The App Content pattern: the page region of an App Shell. It reads the
   shell's --shell-* values and its container width, so it lives inside one. */
/* The page. flat: one card surface, inset from the shell's edges and
   flush below 48rem. card: no surface, the page sits on the canvas and its
   blocks are Cards with appearance="surface". The surface restates
   --background, which components read as "what I sit on". */
.content {
  display: grid;
  grid-row: 2;
  grid-column: -2;
  min-block-size: 0;
  min-inline-size: 0;
  padding: var(--content-flat, var(--space-2)) var(--content-card, 0);
}
.main,
.aside {
  /* stylelint-disable zweihander/no-token-shadow -- content reads the colours of the surface it sits on */
  --background: var(--content-flat, var(--card)) var(--content-card, var(--shell-canvas-solid));
  /* On the canvas (card), text reads the canvas colours, as a transparent piece does. */
  --muted-foreground: var(--content-flat, var(--shell-muted-foreground)) var(--content-card, var(--shell-canvas-muted-foreground));
  --subtle-foreground: var(--content-flat, var(--shell-subtle-foreground)) var(--content-card, var(--shell-canvas-subtle-foreground));
  /* stylelint-enable zweihander/no-token-shadow */
  min-block-size: 0;
  overflow: auto;
  padding: var(--space-container);
  border: 1px solid;
  border-color: var(--content-flat, var(--border)) var(--content-card, transparent);
  border-radius: var(--content-flat, var(--radius-panel)) var(--content-card, 0);
  background: var(--content-flat, var(--card)) var(--content-card, transparent);
  color: var(--content-flat, var(--card-foreground)) var(--content-card, var(--shell-canvas-foreground));
  outline: none;
}

/* The aside: a second column of the same surface, beside the page from
   80rem (Tailwind's xl: with the sidebar and the aside both expanded the
   page keeps about 46rem), else below it. Long words wrap: the column is
   narrow. */
.aside {
  overflow-wrap: anywhere;
}
/* It takes focus so a keyboard can scroll it (see AppContent.tsx). */
.aside:focus-visible {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: calc(-1 * var(--focus-width));
}
/* Stacked, the page and the aside scroll as one, in the region around them:
   each row is as tall as its content, so neither scrolls on its own. */
.withAside {
  grid-auto-rows: max-content;
  gap: var(--content-flat, var(--space-2)) var(--content-card, 0);
  overflow: auto;
}
@container (min-width: 80rem) {
  /* Side by side, each column scrolls on its own. As wide as the expanded
     sidebar, so the frame is symmetric and follows density. */
  .withAside {
    grid-template-rows: minmax(0, 1fr);
    grid-template-columns: minmax(0, 1fr) var(--sidebar-width);
    overflow: hidden;
  }
}

@container (max-width: 47.99rem) {
  .content {
    padding: 0;
    gap: 0;
  }
  .main,
  .aside {
    border-color: transparent;
    border-radius: 0;
  }
  /* Flush, the stacked aside needs a rule to part it from the page. */
  .aside {
    border-block-start-color: var(--content-flat, var(--border)) var(--content-card, transparent);
  }
}
@container (min-width: 64rem) {
  .main,
  .aside {
    padding: var(--space-section);
  }
}
